import { createContainer, createToken } from "@zudojs/container";
import type { Container } from "@zudojs/container";

const VAT_RATE = createToken<number>("VatRate");
function registerShop(container: Container): void {
  container.registerValue(VAT_RATE, 0.075);
}

function createShopContainer(production: boolean): Container {
  const container = createContainer({ freezeRegistrations: production });
  registerShop(container);
  return container;
}

for (const production of [false, true]) {
  const container = createShopContainer(production);
  container.resolve(VAT_RATE);
  try {
    container.replace(VAT_RATE, { useValue: 0 });
