import { createContainer, createToken, describeToken } from "@zudojs/container";
import type { Container } from "@zudojs/container";

interface Payments {
  charge(kobo: number): void;
}
const PAYMENTS = createToken<Payments>("Payments");
class Invoices {
  constructor(readonly payments: Payments) {}
}
class Clock {
  now(): Date {
    return new Date();
  }
}

function verify(container: Container): string[] {
  const failing: string[] = [];
  for (const registration of container.getRegistrations()) {
    try {
      container.resolve(registration.token);
    } catch {
      failing.push(describeToken(registration.token));
    }
  }
  return failing;
}

const container = createContainer();
container.registerClass(Clock, Clock);
container.registerFactory(Invoices, (payments) => new Invoices(payments), [PAYMENTS]);
console.log(verify(container));

