import { ContainerScope, createContainer } from "@zudojs/container";

class RequestLog {
  readonly entries: string[] = [];
  dispose(): void {
    console.log(this.entries.join(" | "));
  }
}

const container = createContainer();
container.registerClass(RequestLog, RequestLog, { scope: ContainerScope.SCOPED });

async function handle(requestId: string): Promise<void> {
  const scope = container.createScope({ name: requestId });
  try {
    scope.resolve(RequestLog).entries.push(`${requestId} start`);
    scope.resolve(RequestLog).entries.push(`${requestId} end`);
  } finally {
    await scope.dispose();
  }
}

await handle("req-1");
await handle("req-2");
